<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><div class="page"><a href="<?= site_url($prefix . '/orders') ?>">← Orders</a><h1>Order <?= esc($order['order_number']) ?></h1><?php if (session('error')): ?><p role="alert"><?= esc(session('error')) ?></p><?php endif ?><?php if (session('success')): ?><p role="status"><?= esc(session('success')) ?></p><?php endif ?><p>Order: <?= esc(str_replace('_', ' ', $order['order_status'])) ?> · Payment: <?= esc($payment['payment_status'] ?? 'unpaid') ?></p><h2>Items</h2><?php foreach ($items as $item): ?><p><?= esc($item['product_name']) ?> × <?= esc($item['quantity']) ?> — <?= format_rupiah((string) $item['subtotal']) ?></p><?php endforeach ?><p>Total: <?= format_rupiah((string) $order['total']) ?></p><h2>Delivery address</h2><p><?= esc($order['recipient_name']) ?>, <?= esc($order['phone']) ?><br><?= esc($order['address']) ?>, <?= esc($order['city']) ?>, <?= esc($order['province']) ?> <?= esc($order['postal_code']) ?></p><?php if ($shipment): ?><p><?= esc($shipment['courier']) ?> — <?= esc($shipment['tracking_number']) ?></p><?php endif ?>
<?php if ($prefix === 'admin' && $order['order_status'] === 'waiting_verification' && $payment && $payment['payment_status'] === 'submitted'): ?><a href="<?= site_url('orders/' . $order['id'] . '/payment/proof') ?>">Download payment proof</a><form class="admin-form" method="post" onsubmit="return confirm('Confirm this payment decision?')" action="<?= site_url('admin/orders/' . $order['id'] . '/verify') ?>"><?= csrf_field() ?><label>Decision<select name="decision"><option value="approve">Approve</option><option value="reject">Reject</option></select></label><label>Reason (required when rejecting)<textarea name="reason"></textarea></label><button type="submit">Confirm decision</button></form><?php endif ?>
<?php if ($prefix === 'admin' && in_array($order['order_status'], ['pending_payment','waiting_verification'], true)): ?><form method="post" onsubmit="return confirm('Cancel this order and restore its stock?')" action="<?= site_url('admin/orders/' . $order['id'] . '/cancel') ?>"><?= csrf_field() ?><button type="submit">Cancel order</button></form><?php endif ?>
<?php if ($order['order_status'] === 'processing'): ?><form class="admin-form" method="post" action="<?= site_url($prefix . '/orders/' . $order['id'] . '/ship') ?>"><?= csrf_field() ?><label>Courier<input name="courier" required maxlength="100"></label><label>Tracking number<input name="tracking_number" required maxlength="100"></label><button type="submit">Mark as shipped</button></form><?php elseif ($order['order_status'] === 'shipped'): ?><form method="post" action="<?= site_url($prefix . '/orders/' . $order['id'] . '/complete') ?>"><?= csrf_field() ?><button type="submit">Mark as completed</button></form><?php endif ?></div><?= $this->endSection() ?>
